import { useEffect, useState } from 'react'
import DashboardLayout from '../components/DashboardLayout.jsx'
import AlertCard from '../components/AlertCard.jsx'
import { api } from '../api.js'
import { fmtDateTime } from '../utils/format.js'

const severityOptions = ['All', 'Critical', 'Warning', 'Normal']

export default function Alerts() {
  const [filter, setFilter] = useState('All')
  const [data, setData] = useState({ alerts: [], counts: { Critical: 0, Warning: 0, Normal: 0 } })
  const [error, setError] = useState('')

  // Alerts are generated by the server when a reading goes out of range.
  // Load them now and re-check every 10 seconds.
  useEffect(() => {
    const load = () =>
      api
        .get(`/alerts?severity=${filter}&limit=50`)
        .then((d) => {
          setData(d)
          setError('')
        })
        .catch((e) => setError(e.message))
    load()
    const timer = setInterval(load, 10000)
    return () => clearInterval(timer)
  }, [filter])

  const { counts } = data

  return (
    <DashboardLayout title="Alerts">
      <div className="mb-6 grid gap-4 sm:grid-cols-3">
        <div className="card p-4">
          <p className="text-xs text-stem/70">Critical</p>
          <p className="mt-1 text-2xl font-semibold text-rose-600">{counts.Critical}</p>
        </div>
        <div className="card p-4">
          <p className="text-xs text-stem/70">Warning</p>
          <p className="mt-1 text-2xl font-semibold text-amber-600">{counts.Warning}</p>
        </div>
        <div className="card p-4">
          <p className="text-xs text-stem/70">Normal</p>
          <p className="mt-1 text-2xl font-semibold text-moss-700">{counts.Normal}</p>
        </div>
      </div>

      <div className="mb-5 flex flex-wrap gap-2">
        {severityOptions.map((opt) => (
          <button
            key={opt}
            onClick={() => setFilter(opt)}
            className={`rounded-full px-3.5 py-1.5 text-sm font-medium transition-colors ${
              filter === opt
                ? 'bg-moss-700 text-white'
                : 'bg-white text-stem ring-1 ring-inset ring-moss-200 hover:bg-moss-50'
            }`}
          >
            {opt}
          </button>
        ))}
      </div>

      {error && <p className="mb-4 rounded-lg bg-rose-50 px-4 py-3 text-sm text-rose-700">{error}</p>}

      <div className="space-y-4">
        {data.alerts.map((a) => (
          <AlertCard
            key={a.id}
            title={a.title}
            description={a.description}
            severity={a.severity}
            time={fmtDateTime(a.createdAt)}
          />
        ))}
        {data.alerts.length === 0 && (
          <div className="card p-10 text-center text-stem">No alerts in this category.</div>
        )}
      </div>
    </DashboardLayout>
  )
}
